def build_daily_rankings(
    stocks: dict[str, dict[str, Any]],
    spx: dict[str, Any],
    regimes: dict[str, dict[str, Any]],
    intervals: Sequence[tuple[str, str]],
    config: E1RSidecarConfig,
) -> dict[str, dict[str, Any]]:
    rankings: dict[str, dict[str, Any]] = {}

    for date, next_date in intervals:
        regime_info = regimes.get(date, {})
        if regime_info.get("regime") != "SIDEWAYS":
            continue

        candidates: list[dict[str, Any]] = []

        for asset in stocks.values():
            if date not in asset["by_date"] or next_date not in asset["by_date"]:
                continue

            candidate = score_candidate(asset, spx, date, config)
            if candidate is None:
                continue

            one_day_return = close_to_close_return(asset, date, next_date)
            if one_day_return is None:
                continue

            candidate["one_day_return"] = one_day_return
            candidates.append(candidate)

        candidates.sort(key=lambda x: x["score"], reverse=True)

        rankings[date] = {
            "date": date,
            "next_date": next_date,
            "regime": "SIDEWAYS",
            "subclass": regime_info.get("subclass") or "NO_SUBCLASS",
            "candidate_count": len(candidates),
            "candidates": candidates,
        }

    return rankings

def build_e1r_sidecar_sleeve(
    stock_dir: Path,
    spx_path: Path,
    regime_path: Path,
    config: E1RSidecarConfig,
) -> dict[str, Any]:
    spx = load_asset(spx_path)
    regimes = load_regimes(regime_path)
    stocks, excluded_found = load_stock_universe(stock_dir, config)

    intervals = build_backtest_intervals(spx, regimes, config)
    rankings = build_daily_rankings(stocks, spx, regimes, intervals, config)
    records = run_daily_rebalanced_sidecar(rankings, spx, regimes, intervals, config)
    summary = summarize_sidecar(records, config)

    regime_counts: dict[str, int] = {}
    subclass_counts: dict[str, int] = {}

    for record in records:
        regime = record["regime"]
        subclass = record["subclass"]
        regime_counts[regime] = regime_counts.get(regime, 0) + 1
        if regime == "SIDEWAYS":
            subclass_counts[subclass] = subclass_counts.get(subclass, 0) + 1

    return {
        "engine": "e1r_sidecar_sleeve",
        "version": "v0.2_formal_sleeve_engine",
        "config": {
            "start_date": config.start_date,
            "end_date": config.end_date,
            "allowed_subclasses": list(config.allowed_subclasses),
            "top_n": config.top_n,
            "gross_exposure": config.gross_exposure,
            "min_history_days": config.min_history_days,
            "min_price": config.min_price,
            "initial_equity": config.initial_equity,
            "excluded_symbols": list(config.excluded_symbols),
        },
        "sample": {
            "intervals": len(intervals),
            "first_interval": {
                "date": intervals[0][0],
                "next_date": intervals[0][1],
            } if intervals else None,
            "last_interval": {
                "date": intervals[-1][0],
                "next_date": intervals[-1][1],
            } if intervals else None,
            "stock_universe_after_exclusions": len(stocks),
            "excluded_symbols_found_in_raw_data": excluded_found,
            "regime_counts": regime_counts,
            "sideways_subclass_counts": subclass_counts,
        },
        "summary": summary,
        "records": records,
    }

def summarize_json(path: Path) -> Dict[str, Any]:
    out: Dict[str, Any] = {
        "path": str(path.relative_to(ROOT)) if path.exists() else str(path.relative_to(ROOT)),
        "exists": path.exists(),
    }
    if not path.exists():
        return out

    obj = read_json(path, default={"__error__": "json_read_failed"})
    if isinstance(obj, dict) and "__error__" in obj:
        out["json_valid"] = False
        out["error"] = obj["__error__"]
        return out

    out["json_valid"] = True
    out["type"] = type(obj).__name__
    if isinstance(obj, dict):
        out["top_keys"] = sorted(obj.keys())
        lists = {}
        for k, v in obj.items():
            if isinstance(v, list):
                sample = v[-1] if v else None
                lists[k] = {
                    "length": len(v),
                    "last_type": type(sample).__name__ if sample is not None else None,
                    "last_keys": sorted(sample.keys()) if isinstance(sample, dict) else None,
                }
        out["lists"] = lists
        metrics = {}
        for k in [
            "strategy_id",
            "variant",
            "variant_id",
            "total_return_pct",
            "spx_return_pct",
            "alpha_pct",
            "max_drawdown_pct",
            "profit_factor",
            "sharpe",
            "sharpe_ratio",
            "final_equity",
            "initial_capital",
        ]:
            if k in obj:
                metrics[k] = obj[k]
        if isinstance(obj.get("sample_validity"), dict):
            metrics["sample_validity"] = obj["sample_validity"]
        out["metrics"] = metrics
    elif isinstance(obj, list):
        out["length"] = len(obj)
        sample = obj[-1] if obj else None
        out["last_type"] = type(sample).__name__ if sample is not None else None
        out["last_keys"] = sorted(sample.keys()) if isinstance(sample, dict) else None

    return out

def import_composer() -> Dict[str, Any]:
    result: Dict[str, Any] = {"ok": False}
    try:
        from src.engine import e1r_composer as composer  # type: ignore

        result["ok"] = True
        result["module"] = "src.engine.e1r_composer"
        result["functions"] = {}
        for name in [
            "build_equity_records_from_returns",
            "extract_core_interval_returns",
            "compound_return",
            "max_drawdown",
            "sharpe_ratio",
            "profit_factor",
        ]:
            fn = getattr(composer, name, None)
            if fn is None:
                result["functions"][name] = {"exists": False}
                continue
            result["functions"][name] = {
                "exists": True,
                "signature": str(inspect.signature(fn)),
                "source_head": "\n".join(inspect.getsource(fn).splitlines()[:40]),
            }
        result["_module_obj"] = composer
    except Exception as exc:
        result["ok"] = False
        result["error"] = type(exc).__name__ + ": " + str(exc)
    return result

def run_build_equity_smoke(composer: Any) -> Dict[str, Any]:
    fn = getattr(composer, "build_equity_records_from_returns", None)
    if fn is None:
        return {"ok": False, "error": "build_equity_records_from_returns not found"}

    attempts = []

    candidate_sets = [
        {
            "name": "daily_return_pct",
            "records": [
                {"date": "2021-06-11", "daily_return_pct": 0.0},
                {"date": "2021-06-14", "daily_return_pct": 1.0},
                {"date": "2021-06-15", "daily_return_pct": -0.5},
            ],
        },
        {
            "name": "daily_return_decimal",
            "records": [
                {"date": "2021-06-11", "daily_return": 0.0},
                {"date": "2021-06-14", "daily_return": 0.01},
                {"date": "2021-06-15", "daily_return": -0.005},
            ],
        },
        {
            "name": "return_pct",
            "records": [
                {"date": "2021-06-11", "return_pct": 0.0},
                {"date": "2021-06-14", "return_pct": 1.0},
                {"date": "2021-06-15", "return_pct": -0.5},
            ],
        },
        {
            "name": "interval_return",
            "records": [
                {"start_date": "2021-06-11", "end_date": "2021-06-14", "interval_return": 0.01},
                {"start_date": "2021-06-14", "end_date": "2021-06-15", "interval_return": -0.005},
            ],
        },
        {
            "name": "strategy_return",
            "records": [
                {"date": "2021-06-11", "strategy_return": 0.0},
                {"date": "2021-06-14", "strategy_return": 0.01},
                {"date": "2021-06-15", "strategy_return": -0.005},
            ],
        },
    ]

    for candidate in candidate_sets:
        try:
            res = fn(candidate["records"], 100000.0)
            attempts.append({
                "name": candidate["name"],
                "ok": True,
                "type": type(res).__name__,
                "length": safe_len(res),
                "sample": res[:5] if isinstance(res, list) else str(res)[:500],
            })
        except Exception as exc:
            attempts.append({
                "name": candidate["name"],
                "ok": False,
                "error": type(exc).__name__ + ": " + str(exc),
            })

    return {
        "ok": any(a.get("ok") for a in attempts),
        "attempts": attempts,
    }

def smoke_mode() -> Dict[str, Any]:
    composer_result = import_composer()
    composer = composer_result.get("_module_obj")
    if composer is None:
        return {
            "composer_import_ok": False,
            "error": composer_result.get("error", "composer import failed"),
        }

    build_smoke = run_build_equity_smoke(composer)

    # Metric utility smoke tests.
    utility_smoke: Dict[str, Any] = {}
    for name, args in [
        ("compound_return", ([0.01, -0.005, 0.02],)),
        ("max_drawdown", ([100.0, 105.0, 101.0, 110.0],)),
        ("sharpe_ratio", ([0.01, -0.005, 0.02],)),
        ("profit_factor", ([0.01, -0.005, 0.02],)),
    ]:
        fn = getattr(composer, name, None)
        if fn is None:
            utility_smoke[name] = {"ok": False, "error": "missing"}
            continue
        try:
            value = fn(*args)
            utility_smoke[name] = {"ok": True, "value": value}
        except Exception as exc:
            utility_smoke[name] = {
                "ok": False,
                "error": type(exc).__name__ + ": " + str(exc),
            }

    return {
        "composer_import_ok": True,
        "build_equity_records_from_returns": build_smoke,
        "utility_functions": utility_smoke,
    }

def normalize_curve(records: list[dict[str, Any]]) -> list[dict[str, Any]]:
    out = []

    for r in records:
        if not isinstance(r, dict):
            continue

        date = first_present(r, ["date", "as_of", "data_date"])
        equity = first_present(r, ["equity", "total_equity", "portfolio_value", "value"])
        spx_equity = first_present(r, ["spx_equity", "spx_value", "benchmark_equity"])
        daily_return = first_present(r, ["daily_return", "return", "ret"])
        core_return = first_present(r, ["core_return", "core_daily_return"])
        sidecar_return = first_present(r, ["sidecar_return", "sidecar_daily_return"])
        combined_return = first_present(r, ["combined_return", "combined_daily_return"])

        if date is None or equity is None:
            continue

        row = {
            "date": date,
            "equity": equity,
        }

        if spx_equity is not None:
            row["spx_equity"] = spx_equity
        if daily_return is not None:
            row["daily_return"] = daily_return
        if core_return is not None:
            row["core_return"] = core_return
        if sidecar_return is not None:
            row["sidecar_return"] = sidecar_return
        if combined_return is not None:
            row["combined_return"] = combined_return

        out.append(row)

    return sorted(out, key=lambda x: x["date"])

def extract_existing_oos_core_equity() -> dict[str, Any]:
    """
    Best-effort bridge to existing legacy OOS equity if present.

    This function does not assume a fixed old schema.
    It tries to find the latest equity value from:
      - exports/oos_summary.json
      - exports/oos_equity_curve.json

    If nothing usable exists, it initializes at 100000.
    """
    summary = read_json(ROOT / "exports/oos_summary.json", {}) or {}
    curve = read_json(ROOT / "exports/oos_equity_curve.json", {}) or {}

    equity = safe_float(
        pick(summary, ["equity", "current_equity", "portfolio_value", "final_equity", "total_equity"]),
        None,
    )

    date = pick(summary, ["date", "status_date", "as_of", "data_date"], None)

    records = None
    if isinstance(curve, list):
        records = curve
    elif isinstance(curve, dict):
        records = (
            curve.get("records")
            or curve.get("equity_curve")
            or curve.get("series")
            or curve.get("data")
        )

    if isinstance(records, list) and records:
        rows = [r for r in records if isinstance(r, dict)]
        if rows:
            rows = sorted(rows, key=lambda r: str(pick(r, ["date", "status_date", "as_of"], "")))
            last = rows[-1]
            equity = safe_float(
                pick(last, ["equity", "total_equity", "portfolio_value", "value"]),
                equity,
            )
            date = pick(last, ["date", "status_date", "as_of"], date)

    if equity is None:
        equity = 100000.0

    return {
        "date": date,
        "equity": equity,
        "source": "legacy_oos_if_available_else_initial_capital",
    }

def infer_spx_forward_return_pct() -> Optional[float]:
    # Optional benchmark cross-check from E1 OOS summary when available.
    e1 = read_json(EXPORT_DIR / "oos_summary.json", {})
    for key in ("spx_forward_return_pct", "spx_return_pct", "benchmark_return_pct"):
        v = to_float(e1.get(key), None) if isinstance(e1, dict) else None
        if v is not None:
            return v
    return None

